package io.openkache.runner.benchmark.measurement;

import static org.junit.jupiter.api.Assertions.*;
import static io.openkache.runner.benchmark.measurement.JvmFixtures.*;
import io.openkache.runner.benchmark.*;
import io.openkache.runner.benchmark.client.*;
import io.openkache.runner.benchmark.execution.ClosedLoopResult.Stage;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;

@Timeout(10)
class JvmWindowCollectorTest {
    private JvmWindowCollector manual(Source source,ClientAccounting client){return new JvmWindowCollector(settings(),source,client::snapshot,source.clock::get,false);}
    @Test void rawTerminalTimeBinsRetainOriginalCohortDespiteLateCallback(){
        var source=new Source();var ledger=new ClientAccounting();var c=manual(source,ledger);c.stage(Stage.PREFLIGHT,100);
        source.clock.set(1_000_000_200L);c.stage(Stage.MEASURE,source.clock.get());
        for(int i=0;i<2;i++){var r=request(i,i==0?TracePhase.WARMUP:TracePhase.MEASURE);ledger.admitted(ClientOutcome.Operation.GET);ledger.terminal(ClientOutcome.Operation.GET,ClientOutcome.Category.SUCCESS);c.outcome(r,100,outcome(r,i==0?1_000_000_099L:1_000_000_100L));}
        c.finished(source.clock.get());var s=c.snapshot();assertTrue(s.valid(),s.toString());assertEquals(0,s.requestWindows().get(0).index());assertEquals(TracePhase.WARMUP,s.requestWindows().get(0).cohortPhase());
        assertEquals(1,s.requestWindows().get(1).index());assertEquals(TracePhase.MEASURE,s.requestWindows().get(1).cohortPhase());assertEquals(1_000_000_100L,s.requestWindows().get(0).endNanos());
    }
    @Test void cumulativeDeltasTelescopeAndEveryActualIntervalIsPreserved(){
        var source=new Source();var c=manual(source,new ClientAccounting());c.stage(Stage.PREFLIGHT,100);source.clock.addAndGet(900_000_000);source.cpu=30;c.sampleNow();source.clock.addAndGet(1_300_000_000);source.cpu=60;c.stage(Stage.LOAD,source.clock.get());source.cpu=80;c.finished(source.clock.get());
        var s=c.snapshot();assertEquals(70,s.samples().stream().skip(1).mapToLong(x->x.resourceDeltas().get("process_cpu_ns").value()).sum());
        for(int i=1;i<s.samples().size();i++){assertEquals(s.samples().get(i-1).intervalEndNanos(),s.samples().get(i).intervalStartNanos());}
        assertTrue(s.samples().get(2).intervalEndNanos()-s.samples().get(2).intervalStartNanos()>JvmWindowCollector.PERIOD_NS);
    }
    @Test void unavailableRequiredSourceIsNotMeasuredAsZero(){var source=new Source();source.unsupported=true;var c=manual(source,new ClientAccounting());c.stage(Stage.PREFLIGHT,100);assertThrows(IllegalStateException.class,()->c.finished(source.clock.get()));var s=c.snapshot();assertFalse(s.valid());assertNull(s.samples().getFirst().jvm().values().get("process_cpu_ns").value());assertTrue(s.issues().contains("REQUIRED_SOURCE_UNAVAILABLE:process_cpu_ns"));}
    @Test void optionalUnavailableFieldsStayNullWithTheirReasons(){var source=new Source();var c=manual(source,new ClientAccounting());c.stage(Stage.PREFLIGHT,100);c.finished(source.clock.get());var value=c.snapshot().samples().getFirst().jvm().values().get("rss_bytes");assertNull(value.value());assertEquals("unsupported",value.status());assertNotNull(value.reason());assertTrue(c.snapshot().valid());}
    @Test void counterResetIsInvalidAndNeverClampedToZero(){var source=new Source();var c=manual(source,new ClientAccounting());c.stage(Stage.PREFLIGHT,100);source.cpu=1;c.sampleNow();assertThrows(IllegalStateException.class,()->c.finished(source.clock.get()));var s=c.snapshot();assertTrue(s.issues().contains("COUNTER_RESET:process_cpu_ns"));assertNull(s.samples().get(1).resourceDeltas().get("process_cpu_ns").value());}
    @Test void processReplacementCannotBecomeASecondReplicaContribution(){var source=new Source();var c=manual(source,new ClientAccounting());c.stage(Stage.PREFLIGHT,100);source.identity="replacement";assertThrows(IllegalStateException.class,c::sampleNow);assertThrows(IllegalStateException.class,()->c.finished(source.clock.get()));assertTrue(c.snapshot().issues().contains("PROCESS_INSTANCE_CHANGED"));}
    @Test void backwardsStageTimeAndSourceClockAreDetected(){var source=new Source();var c=manual(source,new ClientAccounting());c.stage(Stage.PREFLIGHT,100);source.clock.set(600);c.stage(Stage.LOAD,500);assertThrows(IllegalStateException.class,()->c.stage(Stage.MEASURE,400));assertThrows(IllegalStateException.class,()->c.finished(source.clock.get()));assertTrue(c.snapshot().issues().contains("STAGE_CLOCK_ORDER"));
        var bad=new Source();bad.badClock=true;var d=manual(bad,new ClientAccounting());assertThrows(IllegalStateException.class,()->d.stage(Stage.PREFLIGHT,100));assertThrows(IllegalStateException.class,()->d.finished(bad.clock.get()));assertTrue(d.snapshot().issues().contains("SOURCE_CLOCK_ORDER"));}
    @Test void sampleCapacityPreservesEvidenceInsteadOfEvicting(){var source=new Source();var settings=new JvmWindowCollector.Settings("run","slot","clock",JvmWindowCollector.Role.SHARED_FIXTURE,new JvmWindowCollector.Limits(1,10,ms(100)),Set.of());var c=new JvmWindowCollector(settings,source,new ClientAccounting()::snapshot,source.clock::get,false);c.stage(Stage.PREFLIGHT,100);assertThrows(IllegalStateException.class,c::sampleNow);assertThrows(IllegalStateException.class,()->c.finished(source.clock.get()));assertEquals(1,c.snapshot().samples().size());assertTrue(c.snapshot().issues().contains("SAMPLE_CAPACITY"));}
    @Test void outcomeBucketCapacityAndFutureTimeAreNotHidden(){var source=new Source();var settings=new JvmWindowCollector.Settings("run","slot","clock",JvmWindowCollector.Role.SHARED_FIXTURE,new JvmWindowCollector.Limits(10,1,ms(100)),Set.of());var c=new JvmWindowCollector(settings,source,new ClientAccounting()::snapshot,source.clock::get,false);c.stage(Stage.PREFLIGHT,100);source.clock.set(2_000_000_200L);c.outcome(request(0,TracePhase.LOAD),100,outcome(request(0,TracePhase.LOAD),200));assertThrows(IllegalStateException.class,()->c.outcome(request(1,TracePhase.MEASURE),100,outcome(request(1,TracePhase.MEASURE),1_000_000_200)));assertThrows(IllegalStateException.class,()->c.finished(source.clock.get()));assertEquals(1,c.snapshot().requestWindows().size());
        var next=new Source();var d=manual(next,new ClientAccounting());d.stage(Stage.PREFLIGHT,100);assertThrows(IllegalStateException.class,()->d.outcome(request(0,TracePhase.LOAD),100,outcome(request(0,TracePhase.LOAD),1000)));assertThrows(IllegalStateException.class,()->d.finished(next.clock.get()));}
    @Test void concurrentCallbacksOnlyUpdateBoundedCountersAndNeverReadManagementSource()throws Exception{var source=new Source();var ledger=new ClientAccounting();var oneBucket=new JvmWindowCollector.Settings("run","slot","clock",JvmWindowCollector.Role.SHARED_FIXTURE,new JvmWindowCollector.Limits(10,1,ms(100)),Set.of());
        var c=new JvmWindowCollector(oneBucket,source,ledger::snapshot,source.clock::get,false);c.stage(Stage.PREFLIGHT,100);source.clock.set(2000);var start=new CyclicBarrier(4);
        try(var pool=Executors.newFixedThreadPool(4)){List<Future<?>> jobs=new ArrayList<>();for(int t=0;t<4;t++){int thread=t;jobs.add(pool.submit(()->{start.await();for(int i=0;i<500;i++){var r=request(thread*500L+i,TracePhase.MEASURE);c.outcome(r,100,outcome(r,1000));}return null;}));}for(var job:jobs){job.get();}}
        assertEquals(1,source.calls.get());c.finished(source.clock.get());assertTrue(c.snapshot().valid());assertEquals(1,c.snapshot().requestWindows().size());assertEquals(2000,c.snapshot().requestWindows().stream().mapToLong(JvmWindowCollector.RequestWindow::outcomes).sum());}
    @Test void afterFinishCallbacksAreVisibleAndPreviousSnapshotRemainsImmutable(){var source=new Source();var c=manual(source,new ClientAccounting());c.stage(Stage.PREFLIGHT,100);c.finished(source.clock.get());var first=c.snapshot();c.outcome(request(0,TracePhase.MEASURE),100,outcome(request(0,TracePhase.MEASURE),105));assertTrue(first.valid());assertFalse(c.snapshot().valid());assertEquals(1,c.snapshot().lateCallbacks());assertThrows(UnsupportedOperationException.class,()->first.samples().clear());c.close();}
    @Test void snapshotBeforeFinishAndFinishWithoutStagesAreNotQualified(){var source=new Source();var c=manual(source,new ClientAccounting());assertThrows(IllegalStateException.class,c::snapshot);assertThrows(IllegalStateException.class,c::close);assertTrue(c.snapshot().issues().contains("NO_STAGES_OBSERVED"));}
    @Test void sourceExceptionsArePreservedAndDoNotCreateSamples(){var source=new Source();source.fail=true;var c=manual(source,new ClientAccounting());assertThrows(IllegalStateException.class,()->c.stage(Stage.PREFLIGHT,100));assertThrows(IllegalStateException.class,()->c.finished(source.clock.get()));assertTrue(c.snapshot().samples().isEmpty());assertTrue(c.snapshot().issues().stream().anyMatch(s->s.startsWith("SOURCE_EXCEPTION")));}
    @Test void inflightPeakIsExplicitlySampledNotAnInventedTruePeak(){var source=new Source();var ledger=new ClientAccounting();var c=manual(source,ledger);c.stage(Stage.PREFLIGHT,100);ledger.admitted(ClientOutcome.Operation.GET);c.sampleNow();ledger.terminal(ClientOutcome.Operation.GET,ClientOutcome.Category.SUCCESS);c.finished(source.clock.get());assertEquals(1,c.snapshot().sampledPeakPending());assertEquals(0,c.snapshot().samples().getLast().client().pending());}
    @Test void systemSourcesShareOneProcessIdentityAndExposeUnavailableFields(){var a=JvmSnapshotSource.system().sample();var b=JvmSnapshotSource.system().sample();assertEquals(a.processInstanceId(),b.processInstanceId());assertEquals(a.pid(),b.pid());assertEquals(JvmWindowCollector.SOURCE_KEYS,a.values().keySet());assertEquals("unsupported",a.values().get("gc_pause_ns").status());assertNull(a.values().get("rss_bytes").value());}
    @Test void realOneSecondTickerStopsAndCloseIsIdempotent()throws Exception{
        var tick=new CountDownLatch(1);var calls=new java.util.concurrent.atomic.AtomicInteger();var system=JvmSnapshotSource.system();
        var c=new JvmWindowCollector(settings(),()->{var sample=system.sample();if(calls.incrementAndGet()>=2){tick.countDown();}return sample;},new ClientAccounting()::snapshot);
        try{c.stage(Stage.PREFLIGHT,System.nanoTime());assertTrue(tick.await(3,TimeUnit.SECONDS),"periodic capture not observed");}finally{c.finished(System.nanoTime());}
        var s=c.snapshot();assertTrue(s.samplerTerminated());assertTrue(s.samples().size()>=3);c.close();assertEquals(s.samples().size(),c.snapshot().samples().size());
    }
}
